mieterhoehung_sonderkuendigung_beendigungsmodell <- function(zugang_erhoehungsmitteilung_am=NULL, verlangter_erhoehungsbeginn_am=NULL, kuendigungseingang_am=NULL, beendigungsmodell=NULL, bisherige_monatsmiete=NULL, einordnungsnachweis=NULL) {
 .auswahl(beendigungsmodell,'beendigungsmodell',c('kuendigungszugangsmonat','letzter_ausuebungsmonat'));miete <- .geld(bisherige_monatsmiete)
 f <- mieterhoehung_sonderkuendigungsfenster(zugang_erhoehungsmitteilung_am,verlangter_erhoehungsbeginn_am,kuendigungseingang_am,einordnungsnachweis)$wert
 if(!f$erklaerung_im_zeitfenster) .fehler('kuendigungseingang_am','Dieser Ablauf setzt Eingang innerhalb561-Fenster voraus.')
 k <- .datum(kuendigungseingang_am,'kuendigungseingang_am');frueh <- format(.frist(format(k,'%Y-%m-01'),3,'monate','tagesbeginn'),'%Y-%m-%d');spaet <- f$mietende_bei_voller_fristausnutzung
 wert <- list(termin_nach_kuendigungszugangsmonat=frueh,termin_nach_letztem_ausuebungsmonat=spaet,beendigung_nach_vorgegebenem_modell=if(beendigungsmodell=='kuendigungszugangsmonat') frueh else spaet,weitergeltende_monatsmiete=.bruchteile(miete))
 eingaben <- list(zugang_erhoehungsmitteilung_am=zugang_erhoehungsmitteilung_am, verlangter_erhoehungsbeginn_am=verlangter_erhoehungsbeginn_am, kuendigungseingang_am=kuendigungseingang_am, beendigungsmodell=beendigungsmodell, bisherige_monatsmiete=bisherige_monatsmiete, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,"daten_und_EUR","BGB_MIETERHOEHUNG_SONDERKUENDIGUNG_BEENDIGUNGSMODELL",eingaben,list(list(operation="561-Erkl\u00e4rungsfenster pr\u00fcfen und zwei Monatsendbez\u00fcge berechnen; ausschlie\u00dflich rechtlich vorgegebenes Modell ausw\u00e4hlen und unver\u00e4nderte Miete ausweisen.")),eingaben)
 ergebnis$hinweise <- list("561-Beendigungsrechnung als ausdr\u00fccklich bedingtes Modell: Ende des zweiten Monats nach tats\u00e4chlichem K\u00fcndigungszugangsmonat oder nach letztem Aus\u00fcbungsmonat. Beide Termine ausweisen, keine stille Gleichsetzung fr\u00fcher Erkl\u00e4rung mit voller Fristausnutzung. Vorhandenes561-Fenster ber\u00fccksichtigt sp\u00e4ter verlangte Erh\u00f6hung nachBGH25.9.2013VIIIZR280/12; diese Quelle belegt volle Fristausnutzung, nicht universell den fr\u00fcheren Beendigungsbezug. Rechtliche Auswahl daher zwingend. Eingang muss im berechneten Fenster liegen. Bei rechtlich wirksamer561-K\u00fcndigung tritt die Erh\u00f6hung nicht ein, bisherige Monatsmiete bleibt bis Ende ma\u00dfgeblich. Keine automatische Wirksamkeitsfeststellung oder taganteilige Schlussabrechnung. Monatsendtermin nicht wegen Wochenende verschieben.")
 ergebnis
}
